package com.tallyo.tallyo_backend.repository;

import com.tallyo.tallyo_backend.dto.CurrentContext;
import com.tallyo.tallyo_backend.entity.Game;
import com.tallyo.tallyo_backend.enums.League;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.Collection;
import java.util.List;

@Repository
public interface GameRepository extends JpaRepository<Game, Long> {
    List<Game> findByLeague(League league);

    // Removes stale scheduled games that ESPN no longer lists for the fetched
    // window (ESPN replaces placeholder events with new ids, leaving duplicates).
    // Restricted to STATUS_SCHEDULED so ingested scores/details are never touched.
    @Modifying
    @Transactional
    @Query("DELETE FROM Game g WHERE g.league = :league " +
            "AND g.gameStatus = 'STATUS_SCHEDULED' " +
            "AND g.isoDate BETWEEN :windowStart AND :windowEnd " +
            "AND g.id NOT IN :fetchedIds")
    int deleteStaleScheduledGames(@Param("league") League league,
                                  @Param("windowStart") Instant windowStart,
                                  @Param("windowEnd") Instant windowEnd,
                                  @Param("fetchedIds") Collection<Integer> fetchedIds);

    @Query("SELECT g FROM Game g WHERE g.league = :league " +
            "AND (:year = 0 OR g.year = :year) " +
            "AND (:seasonType = 0 OR g.seasonType = :seasonType) " +
            "AND (:week = 0 OR g.week = :week) " +
            "AND (CAST(:startDate AS timestamp) IS NULL OR g.isoDate >= :startDate) " +
            "AND (CAST(:endDate AS timestamp) IS NULL OR g.isoDate < :endDate) " +
            "ORDER BY CASE " +
            "  WHEN g.gameStatus = 'STATUS_IN_PROGRESS' OR g.gameStatus = 'STATUS_END_PERIOD' OR g.gameStatus = 'STATUS_HALFTIME' THEN 1 " +
            "  WHEN g.gameStatus = 'STATUS_SCHEDULED' THEN 2 " +
            "  WHEN g.gameStatus = 'STATUS_FINAL' THEN 3 " +
            "  ELSE 4 " +
            "END, g.isoDate")
    Page<Game> getGames(@Param("league") League league,
                        @Param("year") int year,
                        @Param("seasonType") int seasonType,
                        @Param("week") int week,
                        @Param("startDate") Instant startDate,
                        @Param("endDate") Instant endDate,
                        Pageable pageable);


    @Query(value = """
                SELECT
                    g.year,
                    g.season_type,
                    TO_CHAR(g.iso_date, 'YYYY-MM-DD'),
                    g.week
                FROM games g
                WHERE g.league = :league
                  AND (
                      g.game_status IN ('STATUS_IN_PROGRESS','STATUS_HALFTIME','STATUS_END_PERIOD')
                      OR g.iso_date >= :now
                      OR g.final_game = true
                  )
                ORDER BY
                    CASE
                        WHEN g.game_status IN ('STATUS_IN_PROGRESS','STATUS_HALFTIME','STATUS_END_PERIOD') THEN 0
                        WHEN g.iso_date >= :now THEN 1
                        WHEN g.final_game = true THEN 2
                        ELSE 3
                    END,
                    CASE WHEN g.iso_date >= :now THEN g.iso_date END ASC,
                    CASE WHEN g.iso_date < :now THEN g.iso_date END DESC,
                    g.id DESC
                LIMIT 1
            """, nativeQuery = true)
    CurrentContext findCurrentContext(@Param("league") String league, @Param("now") Instant now);

    @Query(value = "SELECT COUNT(*) > 0 " +
            "FROM games " +
            "WHERE iso_date::timestamp >= NOW() - INTERVAL '24 hours' " +
            "AND (" +
            "  game_status IN ('STATUS_IN_PROGRESS', 'STATUS_HALFTIME', 'STATUS_END_PERIOD') " +
            "  OR " +
            "  (game_status = 'STATUS_SCHEDULED' AND iso_date::timestamp <= NOW())" +
            ")", nativeQuery = true)
    boolean shouldUpdate();

    @Query(value = "SELECT DISTINCT iso_date " +
            "FROM games " +
            "WHERE league = :league",
            nativeQuery = true)
    List<Instant> getGameDates(@Param("league") String league);
}

